import json

from trustchain.graph import build_graph, generate_cyclonedx, paths_to_component, trace_to_roots
from trustchain.discovery.inventory import discover


def _inventory(tmp_path):
    (tmp_path / "package.json").write_text(
        json.dumps({
            "name": "app", "version": "1.0.0", "license": "MIT",
            "dependencies": {"chalk": "^5.0.0"},
        }),
        encoding="utf-8",
    )
    (tmp_path / "yarn.lock").write_text(
        "# This file is generated by running \"yarn install\" inside your project.\n"
        "__metadata:\n  version: 10\n\n"
        "\"chalk@npm:^5.0.0\":\n  version: 5.3.0\n  resolution: \"chalk@npm:5.3.0\"\n"
        "  dependencies:\n    \"ansi-styles\": \"npm:^6.1.0\"\n"
        "  checksum: 10c0/abc\n  languageName: node\n\n"
        "\"ansi-styles@npm:^6.1.0\":\n  version: 6.2.1\n  resolution: \"ansi-styles@npm:6.2.1\"\n"
        "  checksum: 10c0/def\n  languageName: node\n",
        encoding="utf-8",
    )
    return discover(str(tmp_path)).to_dict()


def test_cyclonedx_sbom_structure(tmp_path):
    inv = _inventory(tmp_path)
    sbom = generate_cyclonedx(inv, root_name="app")
    assert sbom["bomFormat"] == "CycloneDX"
    assert sbom["specVersion"] == "1.5"
    assert sbom["metadata"]["component"]["name"] == "app"
    refs = {c["bom-ref"] for c in sbom["components"]}
    assert "pkg:npm/chalk@5.3.0" in refs
    assert "pkg:npm/ansi-styles@6.2.1" in refs
    dep_map = {d["ref"]: d["dependsOn"] for d in sbom["dependencies"]}
    assert "pkg:npm/chalk@5.3.0" in dep_map["root"]
    assert "pkg:npm/ansi-styles@6.2.1" in dep_map["pkg:npm/chalk@5.3.0"]


def test_cyclonedx_scoped_purl():
    sbom = generate_cyclonedx({
        "components": [{
            "key": "npm:@scope/pkg@1.0.0", "ecosystem": "npm", "name": "@scope/pkg",
            "version": "1.0.0", "scope": "direct", "resolved_deps": [],
        }],
        "target": "x",
    })
    assert sbom["components"][0]["purl"] == "pkg:npm/%40scope/pkg@1.0.0"


def test_graph_and_path_tracing(tmp_path):
    inv = _inventory(tmp_path)
    graph = build_graph(inv)
    assert graph.number_of_nodes() == 4  # ROOT, app, chalk, ansi-styles
    key = "npm:ansi-styles@6.2.1"
    paths = paths_to_component(graph, key)
    assert paths and paths[0] == ["ROOT", "npm:chalk@5.3.0", key]
    traces = trace_to_roots(graph, key)
    assert traces and traces[0][0] == "npm:chalk@5.3.0"
    assert traces[0][-1] == key


def test_graph_renders_html(tmp_path):
    from trustchain.graph import render_html
    inv = _inventory(tmp_path)
    graph = build_graph(inv)
    out = tmp_path / "graph.html"
    render_html(graph, out, highlight={"npm:ansi-styles@6.2.1"})
    html = out.read_text(encoding="utf-8")
    assert "ROOT" in html
    assert "ansi-styles@6.2.1" in html
